from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()

    # Remove surrounding parentheses if present
    if len(s) >= 2 and s[0] == '(' and s[-1] == ')':
        s = s[1:-1].strip()

    negative = False
    if s.startswith('-'):
        negative = True
        s = s[1:].lstrip()  # remove the minus sign

    # Remove optional R$ prefix
    if 'R$' in s:
        s = s.replace('R$', '').strip()

    # If no digits at all, raise ValueError
    if not any(ch.isdigit() for ch in s):
        raise ValueError("No digits found in input")

    # Determine whether a comma (decimal separator) is present
    if ',' in s:
        # Split into integer part and cents part at the first comma
        integer_part_str, cents_str = s.split(',', 1)
        # Remove thousand separators '.' from the integer part
        integer_part_clean = integer_part_str.replace('.', '')
        if not integer_part_clean.isdigit():
            raise ValueError(f"Invalid integer part after removing dots: {integer_part_str}")
        cents = int(cents_str)  # exactly two digits for cents, but we accept any integer here
        value_str = f"{integer_part_clean}.{cents}"
    else:
        if '.' in s:
            parts = s.split('.')
            # Validate grouping of dots: after the first group, each part must have exactly three digits
            if len(parts) > 1 and not all(len(p) == 3 for p in parts[1:]):
                raise ValueError(f"Invalid grouping of dots: {s}")
            integer_part_clean = ''.join(parts)  # remove all dots
        else:
            integer_part_clean = s

        cents = 0
        value_str = f"{integer_part_clean}.{cents}"

    try:
        result = Decimal(value_str)
    except Exception as e:
        raise ValueError(f"Cannot parse number '{value_str}'") from e

    if negative:
        result = -result

    return result
