from datetime import date, timedelta

def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    # Helper to find the next business day after a given date (strictly later)
    def next_bd(day):
        candidate = day + timedelta(days=1)
        while candidate.weekday() >= 5 or candidate in holidays:
            candidate += timedelta(days=1)
        return candidate

    # Helper to find the previous business day before a given date (strictly earlier)
    def prev_bd(day):
        candidate = day - timedelta(days=1)
        while candidate.weekday() >= 5 or candidate in holidays:
            candidate -= timedelta(days=1)
        return candidate

    if n == 0:
        # Return d itself only if it is a weekday and not a holiday
        if d.weekday() < 5 and d not in holidays:
            return d
        else:
            # Otherwise move to the next business day after d
            return next_bd(d)
    elif n > 0:
        current = d
        for _ in range(n):
            current = next_bd(current)
        return current
    else:  # n < 0
        current = d
        for _ in range(-n):
            current = prev_bd(current)
        return current
