import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all nodes (keys and values)
    nodes = set()
    for item in deps:
        nodes.add(item)
        for dep in deps[item]:
            nodes.add(dep)

    # Initialize indegree and adjacency list
    indeg = {node: 0 for node in nodes}
    adj = {node: [] for node in nodes}

    for item, deps_list in deps.items():
        for dep in deps_list:
            adj[dep].append(item)   # edge from dependency to dependent
            indeg[item] += 1

    # Start with all nodes that have no dependencies (indegree 0)
    heap = [node for node in nodes if indeg[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            indeg[neighbor] -= 1
            if indeg[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    # If not all nodes were processed, there is a cycle
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")
    return result
