def wrap(text: str, width: int) -> list[str]:
    if not text or width <= 0:
        return []

    # Split the input into words (any whitespace acts as separator)
    words = text.split()

    result_lines = []   # final lines to return
    current_line_tokens = []  # tokens for the line we are currently building

    for word in words:
        if len(word) > width:
            # The word is longer than `width`; break it into pieces of size `width`
            for i in range(0, len(word), width):
                piece = word[i:i+width]
                result_lines.append(piece)
        else:
            # Normal word fits within the line; add to current line's tokens
            current_line_tokens.append(word)

    # If there are leftover tokens from a normal word (i.e., we never started a new line for them),
    # join them with single spaces and add as one final line.
    if current_line_tokens:
        result_lines.append(' '.join(current_line_tokens))

    return result_lines
