def deep_merge(base: dict, override: dict) -> dict:
    result = {}

    # Process keys that exist in base
    for key, val_base in base.items():
        if key in override:
            val_override = override[key]
            # If both values are dictionaries, merge them recursively
            if isinstance(val_base, dict) and isinstance(val_override, dict):
                merged = deep_merge(val_base, val_override)
                result[key] = merged
            else:
                # Override wins unless its value is None (which deletes the key)
                if val_override is not None:
                    result[key] = val_override
        else:
            # Key only in base: keep the base value
            result[key] = val_base

    # Add keys from override that are not present in base and have a non‑None value
    for key, val_override in override.items():
        if key not in result and val_override is not None:
            result[key] = val_override

    return result
