def latest_by_key(records: list[dict], key: str) -> list[dict]:
    from datetime import datetime

    def parse_iso8601(ts: str):
        """Convert an ISO 8601 timestamp string to a timezone‑aware datetime."""
        if ts.endswith('Z'):
            ts = ts[:-1] + '+00:00'
        return datetime.fromisoformat(ts)

    best_by_value = {}   # value -> {'record': rec, 'dt': parsed_dt, 'index': i}
    first_occurrence = {}  # value -> first index where it appears

    for i, rec in enumerate(records):
        val = rec.get(key)                     # value of the grouping key
        updated_at_str = rec.get('updated_at')  # ISO‑8601 string

        if updated_at_str is None:
            # If 'updated_at' is missing we treat it as an earliest instant.
            dt = datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        else:
            dt = parse_iso8601(updated_at_str)

        if val not in first_occurrence:
            first_occurrence[val] = i

        if val not in best_by_value:
            best_by_value[val] = {'record': rec, 'dt': dt, 'index': i}
        else:
            existing = best_by_value[val]
            if dt > existing['dt']:
                best_by_value[val] = {'record': rec, 'dt': dt, 'index': i}
            elif dt == existing['dt'] and i > existing['index']:
                best_by_value[val] = {'record': rec, 'dt': dt, 'index': i}

    # Return records ordered by the first appearance of each key value
    result = [best_by_value[val]['record'] for val in sorted(first_occurrence.keys(), key=lambda v: first_occurrence[v])]
    return result
