import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    """
    Return True if `ip` belongs to any of the CIDR networks in `networks`.

    Parameters:
        ip: string representing an IPv4 or IPv6 address (including IPv4‑mapped
              IPv6 addresses like '::ffff:10.0.0.5').
        networks: list of CIDR network strings, e.g., ['10.0.0.0/8', '2001:db8::/32'].

    Returns:
        True if `ip` is inside at least one of the networks,
        False otherwise.

    Raises:
        ValueError: if any element in `networks` is not a valid CIDR network string.
    """
    # Parse the IP address; invalid IP yields False
    try:
        ip_obj = ipaddress.ip_address(ip)
    except ValueError:
        return False

    for net_str in networks:
        try:
            net_obj = ipaddress.ip_network(net_str)
        except ValueError as exc:
            raise ValueError(f"Invalid network: {net_str}") from exc

        # If the IP is an IPv6‑mapped address, convert it to its underlying IPv4 form
        if isinstance(ip_obj, ipaddress.IPv6Address) and getattr(ip_obj, 'is_ipv4_mapped', False):
            try:
                ip_v4 = ip_obj.to_ipv4()  # returns the IPv4 string for mapped addresses
            except AttributeError:
                # Fallback: extract the IPv4 part manually (e.g., "::ffff:10.0.0.5" -> "10.0.0.5")
                if str(ip_obj).startswith('::ffff:'):
                    ip_v4 = str(ip_obj)[len('::ffff:'):].strip()
                else:
                    # Should not happen for a valid mapped address
                    ip_v4 = None

        # Determine whether we need to compare as IPv4 or IPv6 objects.
        if isinstance(net_obj, ipaddress.IPv4Network):
            # Network is IPv4 → use IPv4 representation of the IP (if any)
            if ip_v4 is not None:
                ip_for_check = ipaddress.IPv4Address(ip_v4)
            else:
                ip_for_check = ipaddress.IPv4Address('0.0.0.0')
        elif isinstance(net_obj, ipaddress.IPv6Network):
            # Network is IPv6 → use the original IP object
            if ip_v4 is not None and isinstance(ip_obj, ipaddress.IPv6Address):
                # For a mapped IPv6 address we want to treat it as IPv4 for this network,
                # but here the network is IPv6 so we keep the original IPv6 object.
                pass  # keep ip_obj
            else:
                ip_for_check = ip_obj
        else:
            raise ValueError(f"Unsupported network type: {net_str}")

        if ip_for_check in net_obj:
            return True

