        raise TypeError(f"threshold must be int, float or decimal.Decimal, got {type(threshold)}")

    def to_decimal(x):
        if isinstance(x, int):
            return decimal.Decimal(x)
        elif isinstance(x, float):
            # Use the shortest decimal representation as written
            return decimal.Decimal(str(x))
        else:  # decimal.Decimal
            return x

    value_dec = to_decimal(value)
    threshold_dec = to_decimal(threshold)

