    def parse_version(v: str):
        # ignore build metadata after '+'
        if '+' in v:
            base_v = v.split('+')[0]
        else:
            base_v = v

        # separate pre-release part (if any)
        if '-' in base_v:
            base_part, pre_part = base_v.split('-', 1)
        else:
            base_part, pre_part = base_v, ''

        # split major, minor, patch from base_part
        base_parts = base_part.split('.')
        major = int(base_parts[0]) if base_parts else 0
        minor = int(base_parts[1]) if len(base_parts) > 1 else 0
        patch = int(base_parts[2]) if len(base_parts) > 2 else 0

        # pre-release identifiers: split by '.' and discard empty tokens
        pre_tokens = [tok for tok in pre_part.split('.') if tok]

        return {'major': major, 'minor': minor, 'patch': patch,
                 'pre_release': pre_tokens}

    def compare_pre_release(p1: list, p2: list) -> int:
        # iterate over tokens up to the shorter length
        for i in range(min(len(p1), len(p2))):
            t1 = p1[i] if i < len(p1) else None
            t2 = p2[i] if i < len(p2) else None

            if t1 is None and t2 is None:
                continue  # both exhausted, move on

            # determine numeric-ness
            def is_numeric(s):
                return s.isdigit()

            # handle cases where one side has no token (shouldn't happen because we checked above)
            if t1 == '' or t2 == '':
                # shorter list is lower when all earlier identifiers equal
                # but here one side lacks a token at this index, meaning it's shorter -> lower for that side
                return -1 if t1 is None else 1

            # both tokens present
            if is_numeric(t1) and is_numeric(t2):
                cmp = int(t1) - int(t2)
            elif is_numeric(t1) != is_numeric(t2):
                # numeric < alphanumeric, so the side that is numeric is lower
                return -1 if is_numeric(t1) else 1
            else:
                # both non-numeric: lexicographic comparison (case‑sensitive)
                cmp = (t1 > t2) - (t1 < t2)

            return cmp

        # all compared tokens equal; shorter list is lower
        if len(p1) < len(p2):
            return -1
        elif len(p1) > len(p2):
            return 1
        else:
            return 0

    pa = parse_version(a)
    pb = parse_version(b)

    # compare major, minor, patch first
    if (pa['major'] != pb['major']) or (pa['minor'] != pb['minor']) or (pa['patch'] != pb['patch']):
        return -1 if pa['major'] < pb['major'] else 1 if pa['major'] > pb['major'] else None
    # base versions equal, now handle pre‑release
    if len(pa['pre_release']) == 0 and len(pb['pre_release']) != 0:
        return -1  # a (no pre) is greater than b (has pre)
    if len(pb['pre_release']) == 0 and len(pa['pre_release']) != 0:
        return 1   # a has pre, b doesn't -> a < b
    return compare_pre_release(pa['pre_release'], pb['pre_release'])
