import heapq

def build_order(deps):
    # Collect all nodes (keys and any values appearing as dependencies)
    all_nodes = set(deps.keys())
    for dep_list in deps.values():
        all_nodes.update(dep_list)

    # Initialize adjacency list and indegree counts for each node
    adj = {node: [] for node in all_nodes}
    indeg = {node: 0 for node in all_nodes}

    # Build edges from each dependency to the dependent item.
    # For a key `node` with dependencies `dep_list`, add edge dep -> node.
    for node, dep_list in deps.items():
        for dep in dep_list:
            adj[dep].append(node)
            indeg[node] += 1

    # Kahn's algorithm using a min‑heap to always pick the alphabetically smallest ready node
    heap = [node for node in all_nodes if indeg[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj.get(u, []):
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)

    # If not all nodes were processed, there is a cycle
    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected")
    return result
