def wrap(text: str, width: int) -> list[str]:
    if not text or not text.strip():
        return []

    words = text.split()
    result = []  # completed lines
    current_line = ""  # line being built

    for word in words:
        if len(word) > width:
            # The word itself is longer than the allowed line length.
            # Break it into chunks of at most `width` characters.
            for i in range(0, len(word), width):
                chunk = word[i:i + width]
                # Decide whether to append this chunk to the current line or start a new line.
                if not current_line or (len(current_line) + 1 + len(chunk) <= width):
                    if current_line == "":
                        result.append(chunk)
                    else:
                        result.append(current_line)
                        current_line = chunk
                else:
                    # Cannot fit in the current line; start a new line with this chunk.
                    if current_line == "":
                        result.append(chunk)
                    else:
                        result.append(current_line)
                        current_line = chunk
            continue

        # Normal word (length <= width).
        if not current_line or (len(current_line) + 1 + len(word) <= width):
            if current_line == "":
                current_line = word
            else:
                current_line += " " + word
        else:
            # The word does not fit on the current line; start a new line.
            result.append(current_line)
            current_line = word

    # Flush any remaining text in the current line.
    if current_line:
        result.append(current_line)

    return result
