def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    # Split the text into lines (without preserving line endings)
    lines = text.splitlines()

    # Locate the header line for the given section
    header_idx = -1
    for i, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith('[') and stripped.endswith(']'):
            inner = stripped[1:-1].strip()  # remove brackets
            if inner == section:
                header_idx = i
                break

    if header_idx == -1:
        raise KeyError(f"Section '{section}' not found")

    new_lines = list(lines)   # copy to modify later
    modified = False

    # Search for the data line inside the identified section (after the header)
    for idx in range(header_idx + 1, len(lines)):
        line = lines[idx]
        stripped = line.strip()

        # Skip comment lines and blank lines
        if not stripped or stripped.startswith('#') or stripped.startswith(';'):
            continue

        # Look for the key on the left side of an '=' sign
        if '=' in line:
            left_part = line.split('=', 1)[0].strip()
            if left_part == key:
                new_lines[idx] = f"{key} = {value}\n"
                modified = True
                break

    if not modified:
        raise KeyError(f"Key '{key}' not found in section '{section}'")

    return '\n'.join(new_lines)
