def deep_merge(base: dict, override: dict) -> dict:
    """
    Return a new dictionary that is the deep merge of `base` and `override`.

    - Keys present only in `override` take their values (unless the value is None,
      in which case the key is omitted).
    - If both base[key] and override[key] are dictionaries, they are merged recursively.
    - For any other types (including lists), the value from `override` replaces the one
      from `base`.
    - The function does not modify either argument and returns a new dictionary that
      contains no references to the original nested objects.
    """
    result = {}
    # Union of all keys from both dictionaries
    all_keys = set(base.keys()) | set(override.keys())

    for key in all_keys:
        bval = base.get(key)   # may be None if key not present; but we check presence below
        ov = override.get(key)

        # If override has the key with value None -> delete the key entirely
        if key in override and ov is None:
            continue

        if key in override:
            # Override provides a non‑None value for this key.
            bval_present = base.get(key)  # may be None or missing, but we know it's present here

            # Both values are dicts → merge recursively
            if isinstance(bval, dict) and isinstance(ov, dict):
                result[key] = deep_merge(bval, ov)
            else:
                # Override wins for non‑dict (or list/tuple) values.
                # To avoid sharing mutable containers, copy lists/tuples when assigning.
                if isinstance(ov, (list, tuple)):
                    result[key] = list(ov)   # shallow copy of the elements
                else:
                    result[key] = ov
        elif key in base:
            # Key exists only in `base`; keep its value but avoid sharing mutable containers.
            bval_present = base.get(key)
            if isinstance(bval, (dict, list)):
                if isinstance(bval, dict):
                    result[key] = {k: v for k, v in bval.items()}  # shallow copy of the outer dict
                else:
                    result[key] = list(bval)   # shallow copy of the elements
            else:
                result[key] = bval

    return result
