import re

def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    # Find all occurrences of a number followed by optional whitespace and one of h, m, s (case-insensitive)
    matches = re.findall(r'(\d+)\s*([hms])', s, flags=re.IGNORECASE)

    if not matches:
        raise ValueError(f"Invalid duration format: {s}")

    total_seconds = 0
    for num_str, unit_char in matches:
        try:
            num = int(num_str)
        except ValueError:
            raise ValueError(f"Invalid number '{num_str}' in string")

        unit = unit_char.lower()
        if unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num
        else:
            raise ValueError(f"Invalid unit '{unit_char}' in string")

    return total_seconds
