from datetime import date, timedelta

def add_business_days(d: date, n: int, holidays: set) -> date:
    """
    Return the date after moving `n` business days (Monday to Friday,
    excluding dates in `holidays`).  `d` itself is never counted as one of
    the `n` days.  For n == 0 return d if it is a business day; otherwise
    return the next business day after d.
    """
    # Helper: check whether a given date is a business day (Mon-Fri and not a holiday)
    def is_business_day(day):
        return day.weekday() < 5 and day not in holidays

    if n == 0:
        if is_business_day(d):
            return d
        else:
            # find the next business day after d
            cur = d
            while True:
                cur += timedelta(days=1)
                if is_business_day(cur):
                    return cur

    steps = abs(n)
    current = d
    for _ in range(steps):
        if n > 0:  # move forward
            while True:
                current += timedelta(days=1)
                if is_business_day(current):
                    break
        else:      # move backward
            while True:
                current -= timedelta(days=1)
                if is_business_day(current):
                    break
    return current
