        minor_str = parts[1] if len(parts) > 1 else ''
        patch_str = parts[2] if len(parts) > 2 else ''
        def to_int(s):
            try:
                return int(s)
            except ValueError:
                # fallback (should not happen for valid semver)
                return 0
        major = to_int(major_str)
        minor = to_int(minor_str)
        patch = to_int(patch_str)
