        if a_is_digit and b_is_digit:
            av = int(id_a)
            bv = int(id_b)
            if av < bv:
                return -1
            elif av > bv:
                return 1
            else:
                return 0
        elif a_is_digit != b_is_digit:
            # numeric identifiers are lower than alphanumeric ones
            if a_is_digit:
                return -1
            else:
                return 1
        else:
