    pb = parse_version(b)

    # compare major version numbers
    if pa[0] != pb[0]:
        return -1 if pa[0] < pb[0] else 1
    if pa[1] != pb[1]:
        return -1 if pa[1] < pb[1] else 1
    if pa[2] != pb[2]:
