    a_has_pre = pa[3] is not None
    b_has_pre = pb[3] is not None

    if a_has_pre != b_has_pre:
        # the version without a pre‑release tag is higher
        return -1 if a_has_pre else 1

    if pa[3] == pb[3]:
        return 0

    # both have pre‑release tags – compare identifiers dot by dot
    a_ids = pa[3].split('.') if pa[3] is not None else []
    b_ids = pb[3].split('.') if pb[3] is not None else []

    for id_a, id_b in zip(a_ids, b_ids):
        cmp_id = compare_identifier(id_a, id_b)
        if cmp_id != 0:
