import re

def wrap(text: str, width: int) -> list[str]:
    if not text or width <= 0:
        return []

    # Split into words (tokens separated by any whitespace)
    tokens = text.split()
    lines = []
    current_line = ""

    for token in tokens:
        if len(token) > width:
            # Token is longer than the line width; split it into chunks of size `width`
            for i in range(0, len(token), width):
                piece = token[i:i+width]
                # Add each chunk as a separate line (no extra spaces between pieces)
                if current_line == "" or not current_line.endswith(' '):
                    # If the current line is empty or does not end with a space,
                    # we can start a new line; otherwise, just append piece.
                    lines.append(current_line.rstrip())
                    current_line = ""
                # Append the piece to the newly started line
                if current_line == "":
                    current_line = piece
                else:
                    # Since pieces belong to the same original word,
                    # we do NOT add a space between them.
                    current_line += piece
            # After processing all chunks, store any remaining content in `current_line`
            if current_line != "":
                lines.append(current_line.rstrip())
        else:
            # Token fits within width; handle spacing with other words on the line
            if current_line == "" or not current_line.endswith(' '):
                # Start a new line for this token (or continue previous line only if it ends with space)
                if current_line != "":
                    lines.append(current_line.rstrip())
                current_line = token
            else:
                # There is already content on the line; add a space and then the token
                current_line += " " + token

    # Append any remaining text in `current_line`
    if current_line != "":
        lines.append(current_line.rstrip())

