    latest_by_val = {}
    for idx, rec in enumerate(records):
        val = rec.get(key)
        upd_str = rec.get('updated_at')
        if upd_str is None:
            dt = None
        else:
            try:
                dt = parse_iso(upd_str)
            except ValueError:
                # If parsing fails we treat the timestamp as missing (earliest possible)
                dt = None

        if val not in latest_by_val:
            latest_by_val[val] = (rec, dt, idx)
        else:
            existing_rec, existing_dt, existing_idx = latest_by_val[val]
            # Prefer later instant; on tie prefer the record that appears later in the list
            if dt > existing_dt or (dt == existing_dt and idx > existing_idx):
                latest_by_val[val] = (rec, dt, idx)

    # Preserve order of first appearance of each distinct value for `key`
    seen = set()
    unique_values = []
    for rec in records:
        val = rec.get(key)
        if val not in seen:
            seen.add(val)
            unique_values.append(val)

    result = [latest_by_val[val][0] for val in unique_values]
    return result
