import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    """
    Return True if `ip` is contained in any of the CIDR strings in `networks`.

    Parameters:
        ip: string representing an IPv4 or IPv6 address (e.g., '192.168.1.1' or
             '::ffff:10.0.0.5'). An invalid IP returns False.
        networks: list of CIDR notation strings, e.g., ['10.0.0.0/8', '2001:db8::/32'].

    Returns:
        bool: True if `ip` is inside any network in `networks`, otherwise False.

    Raises:
        ValueError: If any element of `networks` is not a valid CIDR notation.
    """
    # Parse the input IP address; invalid IP -> return False
    try:
        ip_obj = ipaddress.ip_address(ip)
    except ValueError:
        return False

    for net_str in networks:
        # Parse each network string; raise ValueError if malformed
        try:
            network_obj = ipaddress.ip_network(net_str)
        except ValueError as exc:
            raise ValueError(f"Invalid CIDR network: {net_str}") from exc

        # Check membership, handling possible type mismatches (e.g., IPv4-mapped IPv6 vs IPv4Network)
        try:
            if ip_obj in network_obj:
                return True
        except TypeError:
            # Types differ – e.g., an IPv6 address that is also a mapped IPv4 and an IPv4Network.
            # For such cases we need to extract the underlying IPv4 representation of the IP.
            if isinstance(network_obj, ipaddress.IPv4Network) and isinstance(ip_obj, ipaddress.IPv6Address):
                # Try to get the IPv4 part; fall back to string representation
                try:
                    ip_v4 = ip_obj.ipv4()
                except AttributeError:
                    ip_v4 = str(ip_obj)
            elif isinstance(network_obj, ipaddress.IPv6Network) and isinstance(ip_obj, ipaddress.IPv4Address):
                # For IPv6 network and an IPv4 address (unlikely), we just use the string form
                try:
                    ip_v6 = ip_obj.ipv6()
                except AttributeError:
                    ip_v6 = str(ip_obj)
            else:
                # Same type or no mapping – keep original object
                ip_v4 = ip_obj

            if isinstance(network_obj, ipaddress.IPv4Network):
                # Convert to IPv4Address for membership test
                try:
                    if isinstance(ip_v4, str):
                        ipv4_addr = ipaddress.IPv4Address(ip_v4)
                    else:
                        ipv4_addr = ip_v4
                    return ipv4_addr in network_obj
                except ValueError:
                    # If conversion fails (should not happen for valid input), treat as False
                    continue
            elif isinstance(network_obj, ipaddress.IPv6Network):
                # For IPv6 networks we can directly test with the original object or its string form
                return ip_obj in network_obj
            else:
                # Unexpected combination – skip this network
                continue

    # No matching network found
    return False
